#include <utility>
#include <vector>

// Frame logs "copy" on copy construction and "move" on move construction.
struct Frame {
    std::vector<double> samples;
    Frame() = default;
    Frame(const Frame&);
    Frame(Frame&&) noexcept;
    ~Frame();
};

void load(Frame& f, int n);

Frame decode(int n) {
    Frame f;
    load(f, n);
    if (f.samples.empty())
        return Frame{};
    return std::move(f);
}

int main() {
    Frame a = decode(8);
    Frame b = a;
    Frame c = std::move(b);
}

