#include <vector>

struct Frame {
    std::vector<double> samples;
    Frame() = default;
    Frame(const Frame& o) : samples(o.samples) { std::puts("copy"); }
    Frame(Frame&& o) noexcept : samples(std::move(o.samples)) { std::puts("move"); }
    ~Frame() = default;
};

void load(Frame& f, int n) { f.samples.assign(n, 1.0); }

Frame decode(int n) {
    Frame f;
    load(f, n);
    if (f.samples.empty())
        return Frame{};
    return std::move(f);
}

int main() {
    Frame a = decode(8);
    Frame b = a;
    Frame c = std::move(b);
}

