    double px;
    explicit Quote(double p);
    Quote(const Quote&);
    Quote(Quote&&) noexcept;
    ~Quote();
};

double best(const std::map<std::string, Quote>& book) {
    double top = 0;
    for (auto [symbol, quote] : book)
        if (quote.px > top)
            top = quote.px;
    return top;
}

int main() {
    std::map<std::string, Quote> book;
    book.try_emplace("aapl", 1.0);
    book.try_emplace("msft", 2.0);
    book.try_emplace("goog", 3.0);
    best(book);
}

